import uuid
from datetime import date
from decimal import Decimal

from pydantic import BaseModel, ConfigDict, field_validator

from app.models.asset import AssetType

# Asset types that do not have a market ticker (physical/custom assets).
# Ticker is auto-generated by the backend for these types.
PHYSICAL_ASSET_TYPES = {
    AssetType.real_estate,
    AssetType.vehicle,
    AssetType.other_physical,
    AssetType.other,
}


class AssetCreate(BaseModel):
    ticker: str | None = None  # optional for physical assets; auto-generated if absent
    name: str
    asset_type: AssetType
    currency: str = "RUB"
    estimated_value: Decimal | None = None
    note: str | None = None
    acquisition_date: date | None = None
    is_credit_linked: bool = False
    credit_kind: str | None = None
    credit_note: str | None = None
    include_in_capital: bool = True

    @field_validator("ticker")
    @classmethod
    def ticker_upper(cls, v: str | None) -> str | None:
        if v is None:
            return v
        return v.upper()


class AssetUpdate(BaseModel):
    """Partial update — only fields present in request body are applied."""
    name: str | None = None
    ticker: str | None = None       # market assets only; physical ticker stays hidden
    currency: str | None = None
    estimated_value: Decimal | None = None
    note: str | None = None
    acquisition_date: date | None = None
    is_credit_linked: bool | None = None
    credit_kind: str | None = None
    credit_note: str | None = None
    include_in_capital: bool | None = None


class AssetOut(BaseModel):
    id: uuid.UUID
    ticker: str
    name: str
    asset_type: AssetType
    currency: str
    estimated_value: Decimal | None = None
    note: str | None = None
    acquisition_date: date | None = None
    is_credit_linked: bool = False
    credit_kind: str | None = None
    credit_note: str | None = None
    include_in_capital: bool = True

    model_config = ConfigDict(from_attributes=True)
